375	// Drives the app through its screens, binding only to data-testid (AGENTS.md §2). Every test
376	// arranges its own data with these helpers and asserts through them or through data-testid
377	// directly. An action helper returns what the screen reported: an id when a row was created,
378	// true/false for whether the action went through or the screen refused it (its error element
379	// appeared). It throws when neither a result nor an error shows within the wait, so a screen that
380	// does nothing fails the test instead of passing as "refused".
381	import { expect, type Browser, type Locator, type Page } from '@playwright/test';
382	import { existsSync, readFileSync } from 'node:fs';
383	
384	const AUDIT_FILE = process.env.AUDIT_FILE ?? '../.run/audit.log';
385	const WAIT = 8000;
386	
387	const editing = new WeakMap<Page, string>();
388	
389	export function sheetId(): string {
390	  return 's' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
391	}
392	
393	/** The id a creating helper returned; throws when the screen refused (null) so the failure
394	 *  lands on the arranging line rather than on a later assertion. */
395	export function must(id: string | null): string {
396	  if (id === null) throw new Error('the screen refused this action (its error element appeared)');
397	  return id;
398	}
399	
400	function escapeRe(s: string): string {
401	  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
402	}
403	
404	/** The trimmed text of a locator, read without waiting: '' when it is not on the page. A poll
405	 *  must never use an auto-waiting read (textContent, getAttribute) on an element that may be
406	 *  re-rendered or removed while it polls; that read would block until the test's own timeout. */
407	async function shown(loc: Locator): Promise<string> {
408	  return ((await loc.allTextContents())[0] ?? '').trim();
409	}
410	
411	/** The ids carried by every element matching `loc`, read without waiting. */
412	async function ids(loc: Locator, prefix: string): Promise<string[]> {
413	  const out: string[] = [];
414	  for (const h of await loc.elementHandles()) out.push(idOf(await h.getAttribute('data-testid'), prefix));
415	  return out;
416	}
417	
418	function idOf(testid: string | null, prefix: string): string {
419	  if (!testid || !testid.startsWith(prefix)) throw new Error(`no ${prefix}* id on ${testid}`);
420	  return testid.slice(prefix.length);
421	}
422	
423	/** Poll until `done` holds (true) or `error` is visible (false); throw when neither happens. */
424	async function until(page: Page, done: () => Promise<boolean>, error: Locator, what: string): Promise<boolean> {
425	  const deadline = Date.now() + WAIT;
426	  while (Date.now() < deadline) {
427	    if (await done()) return true;
428	    if (await error.isVisible().catch(() => false)) return false;
429	    await page.waitForTimeout(50);
430	  }
431	  if (await done()) return true;
432	  throw new Error(`${what}: neither a result nor an error appeared within ${WAIT}ms`);
433	}
