436	
437	export async function userPage(browser: Browser, user: string, sheet: string): Promise<Page> {
438	  const page = await (await browser.newContext()).newPage();
439	  await page.goto('/');
440	  await page.getByTestId('signin-name').fill(user);
441	  await page.getByTestId('signin-submit').click();
442	  await expect(page.getByTestId('current-user')).toHaveText(user);
443	  await loadSheet(page, sheet);
444	  return page;
445	}
446	
447	export async function loadSheet(page: Page, sheet: string): Promise<void> {
448	  await page.getByTestId('sheet-id-input').fill(sheet);
449	  await page.getByTestId('sheet-load').click();
450	  await expect(page.getByTestId('sheet-current-id')).toHaveText(sheet);
451	}
452	
453	/** Re-load the active sheet so the screen shows what the store holds now. */
454	export async function refresh(page: Page): Promise<void> {
455	  const sheet = (await page.getByTestId('sheet-current-id').textContent() ?? '').trim();
456	  await loadSheet(page, sheet);
457	}
458	
459	export async function setToday(page: Page, date: string): Promise<void> {
460	  await page.getByTestId('sheet-today-input').fill(date);
461	  await page.getByTestId('sheet-today-save').click();
462	  await expect(page.getByTestId('sheet-today')).toHaveText(date);
463	}
464	
465	// ---- people ----------------------------------------------------------------------------------
466	
467	export function row(page: Page, personId: string): Locator {
468	  return page.getByTestId(`person-row-${personId}`);
469	}
470	
471	function rows(page: Page): Locator {
472	  return page.locator('[data-testid^="person-row-"]');
473	}
474	
475	function rowsNamed(page: Page, name: string): Locator {
476	  const re = new RegExp(`^\\s*${escapeRe(name.trim())}\\s*$`, 'i');
477	  return rows(page).filter({ has: page.getByTestId('person-name').filter({ hasText: re }) });
478	}
479	
480	/** The id of the (newest) person row showing this name. */
481	export async function personId(page: Page, name: string): Promise<string> {
482	  const r = rowsNamed(page, name).last();
483	  await expect(r).toBeVisible();
484	  return idOf(await r.getAttribute('data-testid'), 'person-row-');
485	}
486	
487	async function fillPersonForm(page: Page, f: { name?: string; grade?: string; gradeFrom?: string }) {
488	  if (f.name !== undefined) await page.getByTestId('person-form-name').fill(f.name);
489	  if (f.grade !== undefined) await page.getByTestId('person-form-grade').selectOption(f.grade);
490	  if (f.gradeFrom !== undefined) await page.getByTestId('person-form-grade-from').fill(f.gradeFrom);
491	}
492	
493	/** Add a person through the form. The new row's id, or null when the form refused. */
494	export async function addPerson(page: Page, f: { name: string; grade: string; gradeFrom?: string }): Promise<string | null> {
495	  const before = await ids(rows(page), 'person-row-');
496	  await fillPersonForm(page, f);
497	  await page.getByTestId('person-form-submit').click();
498	  const ok = await until(page, async () => (await rows(page).count()) > before.length,
499	    page.getByTestId('person-form-error'), 'add person');
500	  if (!ok) return null;
501	  const fresh = (await ids(rows(page), 'person-row-')).filter((id) => !before.includes(id));
502	  return fresh.length === 1 ? fresh[0] : personId(page, f.name);
503	}
504	
505	export async function editOpen(page: Page, personId: string): Promise<void> {
506	  await page.getByTestId(`person-edit-${personId}`).click();
507	  await expect(page.getByTestId('person-form-name')).not.toHaveValue('');
508	  editing.set(page, personId);
509	}
510	
511	/** Save the open editor with these changes; true when saved, false when the form refused. */
512	export async function editSave(page: Page, f: { name?: string; grade?: string; gradeFrom?: string }): Promise<boolean> {
513	  const id = editing.get(page);
514	  if (!id) throw new Error('editSave without editOpen');
515	  await fillPersonForm(page, f);
516	  await page.getByTestId('person-form-submit').click();
517	  const r = row(page, id);
518	  return until(page, async () => {
519	    if (f.name !== undefined && await shown(r.getByTestId('person-name')) !== f.name.trim()) return false;
520	    if (f.grade !== undefined && await shown(r.getByTestId('person-grade')) !== f.grade) return false;
521	    return !(await page.getByTestId('person-form-error').isVisible().catch(() => false));
522	  }, page.getByTestId('person-form-error'), 'save person');
523	}
524	
525	export async function editPerson(page: Page, personId: string, f: { name?: string; grade?: string; gradeFrom?: string }): Promise<boolean> {
526	  await editOpen(page, personId);
527	  return editSave(page, f);
528	}
529	
530	export async function retire(page: Page, personId: string, date: string): Promise<boolean> {
531	  const r = row(page, personId);
532	  await r.getByTestId('person-retire-date').fill(date);
533	  await r.getByTestId('person-retire').click();
534	  return until(page, async () => (await r.count()) === 0
535	    || await shown(r.getByTestId('person-retired')) === 'yes',
536	    r.getByTestId('person-error'), 'retire');
537	}
538	
539	/** Take a statement for the person: true once the row's statement count has moved on. */
540	export async function statement(page: Page, personId: string): Promise<boolean> {
541	  const r = row(page, personId);
542	  const was = await shown(r.getByTestId('person-statement-count'));
543	  await r.getByTestId('person-statement').click();
544	  return until(page, async () => await shown(r.getByTestId('person-statement-count')) !== was,
545	    r.getByTestId('person-error'), 'statement');
546	}
547	
548	/** Toggle the hold (no dates), or add a hold with dates: true once the row shows it. */
549	export async function hold(page: Page, personId: string, f: { from?: string; to?: string }): Promise<boolean> {
550	  const r = row(page, personId);
551	  const dated = f.from !== undefined || f.to !== undefined || (await r.getByTestId('person-hold-from').count()) > 0;
552	  const wasText = await shown(r.getByTestId('person-hold'));
553	  const lines = r.getByTestId('person-hold-line');
554	  const wasLines = await lines.count();
555	  if (f.from !== undefined) await r.getByTestId('person-hold-from').fill(f.from);
556	  if (f.to !== undefined) await r.getByTestId('person-hold-to').fill(f.to);
557	  await r.getByTestId('person-hold-toggle').click();
558	  return until(page, async () => dated
559	    ? (await lines.count()) > wasLines
560	    : await shown(r.getByTestId('person-hold')) !== wasText,
561	    r.getByTestId('person-error'), 'hold');
562	}
563	
564	export async function showRetired(page: Page, on: boolean): Promise<void> {
565	  await page.getByTestId('show-retired').setChecked(on);
566	}
567	
568	export async function addPatron(page: Page, personId: string, patronName: string): Promise<boolean> {
569	  const r = row(page, personId);
570	  const names = async () => (await shown(r.getByTestId('person-patrons'))).split(',').filter((s) => s.trim()).length;
571	  const before = await names();
572	  try {
573	    await r.getByTestId('person-patron-select').selectOption({ label: patronName }, { timeout: 2000 });
574	  } catch {
575	    return false;             // not offered: the screen refuses it by leaving it out
576	  }
577	  await r.getByTestId('person-patron-add').click();
578	  return until(page, async () => (await names()) > before, r.getByTestId('person-patron-error'), 'add patron');
579	}
580	
581	// ---- claims ----------------------------------------------------------------------------------
582	
583	export function claimRow(page: Page, claimId: string): Locator {
584	  return page.getByTestId(`claim-row-${claimId}`);
585	}
586	
587	function claimRows(scope: Locator | Page): Locator {
588	  return scope.locator('[data-testid^="claim-row-"]');
589	}
590	
591	function personRowOf(page: Page, claimId: string): Locator {
592	  return rows(page).filter({ has: claimRow(page, claimId) });
593	}
594	
595	export async function claimCount(page: Page, personId: string): Promise<number> {
596	  return claimRows(row(page, personId)).count();
597	}
598	
599	type ClaimFields = { amount?: string; date?: string; note?: string; corrects?: string };
600	
601	async function fillClaimForm(r: Locator, f: ClaimFields) {
602	  if (f.amount !== undefined) await r.getByTestId('claim-form-amount').fill(f.amount);
603	  if (f.date !== undefined) await r.getByTestId('claim-form-date').fill(f.date);
604	  if (f.note !== undefined) await r.getByTestId('claim-form-note').fill(f.note);
605	  if (f.corrects !== undefined) await r.getByTestId('claim-form-corrects').fill(f.corrects);
606	}
607	
608	async function newestClaim(r: Locator): Promise<string> {
609	  const first = claimRows(r).first();
610	  await expect(first, 'the new claim row under its person').toBeVisible();
611	  return idOf(await first.getAttribute('data-testid'), 'claim-row-');
612	}
613	
614	/** Add a claim from the person's row. The new claim's id (listed newest first), or null. */
615	export async function addClaim(page: Page, personId: string, f: ClaimFields & { amount: string }): Promise<string | null> {
616	  const r = row(page, personId);
617	  const before = await claimRows(r).count();
618	  await fillClaimForm(r, f);
619	  await r.getByTestId('claim-form-submit').click();
620	  const ok = await until(page, async () => (await claimRows(r).count()) > before,
621	    r.getByTestId('claim-form-error'), 'add claim');
622	  return ok ? newestClaim(r) : null;
623	}
624	
625	/** Submit the claim form twice in quick succession (a double click on submit). */
626	export async function addClaimTwice(page: Page, personId: string, f: ClaimFields & { amount: string }): Promise<string | null> {
627	  const r = row(page, personId);
628	  const before = await claimRows(r).count();
629	  await fillClaimForm(r, f);
630	  await r.getByTestId('claim-form-submit').dblclick();
631	  const ok = await until(page, async () => (await claimRows(r).count()) > before,
632	    r.getByTestId('claim-form-error'), 'add claim twice');
633	  await page.waitForTimeout(500);          // let a second record land, if the app stores one
634	  return ok ? newestClaim(r) : null;
635	}
636	
637	/** Edit a claim through its edit button and the claim form; true when the row shows the change. */
638	export async function editClaim(page: Page, claimId: string, f: ClaimFields): Promise<boolean> {
639	  const c = claimRow(page, claimId);
640	  const r = personRowOf(page, claimId);
641	  await c.getByTestId('claim-edit').click();
642	  if (await c.getByTestId('claim-error').isVisible().catch(() => false)) return false;
643	  await fillClaimForm(r, f);
644	  await r.getByTestId('claim-form-submit').click();
645	  const error = c.getByTestId('claim-error').or(r.getByTestId('claim-form-error'));
646	  return until(page, async () => {
647	    for (const [k, v] of Object.entries(f)) {
648	      const cell = await shown(c.getByTestId(`claim-${k}`));
649	      if (cell !== v) return false;
650	    }
651	    return true;
652	  }, error, 'edit claim');
653	}
654	
655	/** open | settle | void | approve | reject(reason): true when the status changed. */
656	export async function claimAction(page: Page, claimId: string, action: string, reason?: string): Promise<boolean> {
657	  const c = claimRow(page, claimId);
658	  const was = await shown(c.getByTestId('claim-status'));
659	  if (reason !== undefined) await c.getByTestId('claim-reject-reason').fill(reason);
660	  await c.getByTestId(`claim-${action}`).click();
661	  return until(page, async () => await shown(c.getByTestId('claim-status')) !== was,
662	    c.getByTestId('claim-error'), `claim ${action}`);
663	}
664	
665	export async function numbersOf(page: Page, claimIds: string[]): Promise<string[]> {
666	  await refresh(page);
667	  const out: string[] = [];
668	  for (const id of claimIds) {
669	    await expect(claimRow(page, id)).toBeVisible();
670	    out.push(await shown(claimRow(page, id).getByTestId('claim-number')));
671	  }
672	  return out;
673	}
674	
675	export async function reassign(page: Page, claimId: string, toName: string): Promise<boolean> {
676	  const c = claimRow(page, claimId);
677	  await c.getByTestId('claim-reassign-to').selectOption({ label: toName });
678	  await c.getByTestId('claim-reassign').click();
679	  return until(page, async () => (await rowsNamed(page, toName).filter({ has: claimRow(page, claimId) }).count()) > 0,
680	    c.getByTestId('claim-error'), 'reassign');
681	}
682	
683	export async function bulkOpen(page: Page, claimIds: string[]): Promise<{ opened: number; refused: number }> {
684	  for (const id of claimIds) await claimRow(page, id).getByTestId('claim-select').setChecked(true);
685	  await page.getByTestId('bulk-open').click();
686	  await expect(page.getByTestId('bulk-opened')).toBeVisible();
687	  return {
688	    opened: Number(await shown(page.getByTestId('bulk-opened'))),
689	    refused: Number(await shown(page.getByTestId('bulk-refused'))),
690	  };
691	}
692	
693	/** The quick-add bar: the new claim's id, or null when refused. */
694	export async function quickAdd(page: Page, f: { name: string; amount: string }): Promise<string | null> {
695	  const before = await ids(claimRows(page), 'claim-row-');
696	  await page.getByTestId('quick-name').fill(f.name);
697	  await page.getByTestId('quick-amount').fill(f.amount);
698	  await page.getByTestId('quick-submit').click();
699	  const ok = await until(page, async () => (await claimRows(page).count()) > before.length,
700	    page.getByTestId('quick-error'), 'quick add');
701	  if (!ok) return null;
702	  const fresh = (await ids(claimRows(page), 'claim-row-')).filter((id) => !before.includes(id));
703	  return fresh.length === 1 ? fresh[0] : newestClaim(rowsNamed(page, f.name).last());
704	}
705	
706	// ---- rates, periods, settings, roles, import, export ----------------------------------------
707	
708	export async function setRate(page: Page, f: { grade: string; pct: string; from?: string }): Promise<boolean> {
709	  await page.getByTestId('rate-form-grade').selectOption(f.grade);
710	  await page.getByTestId('rate-form-pct').fill(f.pct);
711	  if (f.from !== undefined) await page.getByTestId('rate-form-from').fill(f.from);
712	  await page.getByTestId('rate-form-submit').click();
713	  const r = page.getByTestId(`rate-row-${f.grade}-${f.from ?? 'start'}`);
714	  return until(page, async () => await shown(r.getByTestId('rate-pct')) === f.pct,
715	    page.getByTestId('rate-form-error'), 'set rate');
716	}
717	
718	export async function addPeriod(page: Page, f: { name: string; from: string; to: string }): Promise<boolean> {
719	  const all = page.locator('[data-testid^="period-row-"]');
720	  const before = await all.count();
721	  await page.getByTestId('period-form-name').fill(f.name);
722	  await page.getByTestId('period-form-from').fill(f.from);
723	  await page.getByTestId('period-form-to').fill(f.to);
724	  await page.getByTestId('period-form-submit').click();
725	  return until(page, async () => (await all.count()) > before, page.getByTestId('period-form-error'), 'add period');
726	}
727	
728	/** close | reopen: true when the period's closed flag changed. */
729	export async function periodAction(page: Page, name: string, action: string): Promise<boolean> {
730	  const r = page.getByTestId(`period-row-${name}`);
731	  const was = await shown(r.getByTestId('period-closed'));
732	  await r.getByTestId(`period-${action}`).click();
733	  return until(page, async () => await shown(r.getByTestId('period-closed')) !== was,
734	    r.getByTestId('period-error'), `period ${action}`);
735	}
736	
737	export async function setSetting(page: Page, key: string, value: string): Promise<void> {
738	  await page.getByTestId(`setting-${key}`).fill(value);
739	  await page.getByTestId('settings-save').click();
740	  await expect(page.getByTestId(`setting-${key}-current`)).toHaveText(value);
741	}
742	
743	export async function setRole(page: Page, user: string, role: string): Promise<boolean> {
744	  await page.getByTestId('role-form-user').fill(user);
745	  await page.getByTestId('role-form-role').fill(role);
746	  await page.getByTestId('role-form-submit').click();
747	  const r = page.getByTestId(`role-row-${user}`);
748	  return until(page, async () => await shown(r.getByTestId('role-value')) === role,
749	    page.getByTestId('role-form-error'), 'set role');
750	}
751	
752	export async function exportCsv(page: Page): Promise<string> {
753	  const [download] = await Promise.all([page.waitForEvent('download'), page.getByTestId('export-people').click()]);
754	  const path = await download.path();
755	  if (!path) throw new Error('export produced no file');
756	  return readFileSync(path, 'utf8');
757	}
758	
759	// ---- audit -----------------------------------------------------------------------------------
760	
761	/** The audit lines written for this sheet, in file order. */
762	export function auditFor(sheet: string): string[] {
763	  if (!existsSync(AUDIT_FILE)) return [];
764	  return readFileSync(AUDIT_FILE, 'utf8').split('\n').filter((l) => l.includes(` sheet=${sheet} `));
765	}
766	
767	/** The sheet's audit lines are exactly these, in order; a line may carry further fields after
768	 *  the expected ones (a later feature may extend a line, never change or reorder its fields). */
769	export function expectAudit(sheet: string, expected: string[]): void {
770	  const lines = auditFor(sheet);
771	  expect(lines.length, `audit lines for ${sheet}:\n${lines.join('\n')}`).toBe(expected.length);
772	  lines.forEach((line, i) => {
773	    const e = expected[i];
774	    const ok = line === e || line.startsWith(e + ' ');
775	    expect(ok, `audit line ${i + 1}\n  expected: ${e}\n  actual:   ${line}`).toBe(true);
776	  });
777	}
